. (Join-Path $PSScriptRoot 'common.ps1')
if(Test-Path (Join-Path $script:LiveARoot 'readiness-plan.json')){throw 'READINESS_ALREADY_PREPARED'}
$human=Read-LiveHuman;$baseline=Check-LiveBaseline
. (Join-Path (Get-Location).Path 'labs/tiktok/ui-source-prelaunch/wiring.ps1')
$plan=Get-PrelaunchPlan
$old=Get-Content docs/evidence/ui-source-runtime-offline-probe-20261019/backend/plan.json -Raw|ConvertFrom-Json
$run=[Guid]::NewGuid().ToString('N');$name='wed-source-'+$run+'-readiness-clock';$rows=@();$i=0
foreach($source in @($plan.mounts.source|Sort-Object -Unique)){$rows+=@{source=(Resolve-Path $source).Path;sha256=(Get-FileHash $source).Hash.ToLowerInvariant();target=('/probe/src/'+$i.ToString('D4'))};$i++}
$clock=(Resolve-Path (Join-Path $PSScriptRoot 'clock.cjs')).Path
$argv=@('create','--pull=never','--platform','linux/amd64','--name',$name,'--label',('com.wed-snap.run='+$run),'--label','com.wed-snap.task=live-readiness-20261019','--network','none','--ipc','private','--cgroupns','private','--read-only','--user','1000:1000','--memory','512m','--memory-swap','512m','--cpus','0.75','--pids-limit','160','--cap-drop','ALL','--security-opt','no-new-privileges:true','--restart','no','--entrypoint','node','-e','STEP5_EXECUTE_SOURCE=0')
foreach($m in $rows){$argv+=@('--mount',('type=bind,source='+$m.source+',target='+$m.target+',readonly'))}
$argv+=@('--mount',('type=bind,source='+$clock+',target=/probe/clock.cjs,readonly'),$plan.resources.roles[0].image,'/probe/clock.cjs',$run,[string]$rows.Count)
if((($argv|ForEach-Object{$_.Length+3}|Measure-Object -Sum).Sum+200) -ge 32767){throw 'READINESS_ARGV_TOO_LONG'}
$historical=Get-Content docs/evidence/tiktok-photo-source-fixed-runtime-20261015/source-once/expected-source.json -Raw|ConvertFrom-Json
$matched=@();$different=@();foreach($p in $historical){if(!(Test-Path $p.path) -or (Get-FileHash $p.path).Hash.ToLowerInvariant() -cne $p.sha256){$different+=$p.path}else{$matched+=$p.path}}
Save-New (Join-Path $script:LiveARoot 'historical-capability.json') @{classification='HISTORICAL_ONLY_NOT_FRESH_ENVIRONMENT_OR_NEW_PHASE_CLOSURE';assessment=Live-Ref 'docs/evidence/tiktok-photo-source-fixed-live-review-20261015/ASSESSMENT.md';reviewManifest=Live-Ref 'docs/evidence/tiktok-photo-source-fixed-live-review-20261015/manifest.json';expectedSource=Live-Ref 'docs/evidence/tiktok-photo-source-fixed-runtime-20261015/source-once/expected-source.json';matched=$matched;different=$different;previous=@{roles=4;networks=2;memoryMiB=800};proposed=@{roles=5;networks=3;memoryMiB=928};freshProofRequiredAtFinal=$true;sourceCalls=0}
$pins=@($baseline.pins)+@($plan.pins)+@{path=$clock;sha256=(Get-FileHash $clock).Hash.ToLowerInvariant()}
Save-New (Join-Path $script:LiveARoot 'readiness-plan.json') @{schema='wed-live-readiness-batch-v1';runID=$run;name=$name;image=$plan.resources.roles[0].image;argv=$argv;rows=$rows;taskMarker='live-readiness-20261019';workMs=60000;hardMs=80000;nativeMs=15000;captureBytes=65536;maxRunning=1;customNetworks=0;publishPorts=0;temporaryPortBind='127.0.0.1:5206_RELEASE_IMMEDIATELY_NOT_RESERVATION';sourceGate=$false;humanRef=Live-Ref $script:HumanPath;taskRef=Live-Ref $script:LiveTask;binary=$old.binary;binarySHA=$old.binarySHA;MVID=$old.MVID;helperSource=$old.helperSource;helperSHA=$old.helperSHA;docker=$old.docker;dockerSHA=$old.dockerSHA;endpoint=$old.endpoint;python='C:/Users/LENOVO/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe';pythonSHA=(Get-FileHash 'C:/Users/LENOVO/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe').Hash.ToLowerInvariant();sourcePins=@(Get-ChildItem $PSScriptRoot -File|Sort-Object Name|ForEach-Object{@{path=$_.FullName;sha256=(Get-FileHash $_.FullName).Hash.ToLowerInvariant()}});baselinePins=$pins;sourcePlanPins=$plan.pins;allocation=Get-Content labs/tiktok/ui-source-owner-native/allocation.json -Raw|ConvertFrom-Json;utc=[DateTimeOffset]::UtcNow.ToString('o')}
Write-Output ('PREPARED_READINESS_ONLY '+(Get-FileHash (Join-Path $script:LiveARoot 'readiness-plan.json')).Hash.ToLowerInvariant())
